PROGRAM TankLamp
VAR_INPUT AboveLow AT %I0.0 : BOOL; AboveHigh AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT LampLow AT %QX0.0 : BOOL; LampOk AT %QX0.1 : BOOL; LampHigh AT %QX0.2 : BOOL; END_VAR
LampLow := FALSE; LampOk := FALSE; LampHigh := FALSE;
IF NOT AboveLow THEN LampLow := TRUE;
ELSIF NOT AboveHigh THEN LampOk := TRUE;
ELSE LampHigh := TRUE;
END_IF;
END_PROGRAM

PROGRAM TankLamp
VAR_INPUT AboveLow AT %I0.0 : BOOL; AboveHigh AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT LampLow AT %QX0.0 : BOOL; LampOk AT %QX0.1 : BOOL; LampHigh AT %QX0.2 : BOOL; END_VAR
LampLow := NOT AboveLow;
LampOk := AboveLow AND NOT AboveHigh;
LampHigh := AboveHigh;
END_PROGRAM

PROGRAM TankLamp
VAR_INPUT AboveLow AT %I0.0 : BOOL; AboveHigh AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT LampLow AT %QX0.0 : BOOL; LampOk AT %QX0.1 : BOOL; LampHigh AT %QX0.2 : BOOL; END_VAR
IF NOT AboveLow THEN LampLow := TRUE; LampOk := FALSE; LampHigh := FALSE; END_IF;
IF AboveLow AND NOT AboveHigh THEN LampLow := FALSE; LampOk := TRUE; LampHigh := FALSE; END_IF;
IF AboveHigh THEN LampLow := FALSE; LampOk := FALSE; LampHigh := TRUE; END_IF;
END_PROGRAM

